    const name = relative.slice(index + 1);
    if (!fdEntryExists(sourceParent, name)) return null;
    backupRunDirectory();
    const backupRelative = `${BACKUP_DIR}/${BACKUP_RUN}/${relative}`;
    const backupIndex = backupRelative.lastIndexOf('/');
